    fn get_child_states(state: Self::State) -> &'static [Self::State] {
        match state {
            SyncClientState::Client => &[
                SyncClientState::Idle,
                SyncClientState::Deleting,
                SyncClientState::Uploading,
                SyncClientState::Listing,
            ],
            _ => &[],
        }
    }

    // §scxml-3.3: a compound state's initial transition target, as written —
    // the engine's entry procedures dereference a <history> among them.
    fn get_initial_targets(
        state: Self::State,
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        match state {
            SyncClientState::Client => &[::sce_rust_runtime::EntryTarget::State(
                SyncClientState::Idle,
            )],
            _ => &[],
        }
    }

    // §scxml-3.2: the target of the document's own initial transition, as written.
    fn get_document_initial_targets(
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        &[::sce_rust_runtime::EntryTarget::State(
            SyncClientState::Client,
        )]
    }

    // §scxml-3.10: the state a <history> is declared in.
    fn get_history_parent(history: Self::History) -> Self::State {
        match history {}
    }

    // §scxml-3.10.2: a <history>'s default transition target, as written.
    fn get_history_default_targets(
        history: Self::History,
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        match history {}
    }

    fn get_document_order(state: Self::State) -> u32 {
        match state {
            SyncClientState::Client => 0,
            SyncClientState::Deleting => 2,
            SyncClientState::Idle => 1,
            SyncClientState::Listing => 4,
            SyncClientState::Uploading => 3,
        }
    }

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            SyncClientEvent::ErrorExecution => "error.execution",
            SyncClientEvent::SyncPage => "sync.page",
            SyncClientEvent::SyncPhaseDone => "sync.phase.done",
            SyncClientEvent::SyncResponse => "sync.response",
            SyncClientEvent::SyncStart => "sync.start",
            SyncClientEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "error.execution" => Some(SyncClientEvent::ErrorExecution),
            "sync.page" => Some(SyncClientEvent::SyncPage),
            "sync.phase.done" => Some(SyncClientEvent::SyncPhaseDone),
            "sync.response" => Some(SyncClientEvent::SyncResponse),
            "sync.start" => Some(SyncClientEvent::SyncStart),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            SyncClientState::Client => "client",
            SyncClientState::Deleting => "deleting",
            SyncClientState::Idle => "idle",
            SyncClientState::Listing => "listing",
            SyncClientState::Uploading => "uploading",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the `StateChain` `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "client" => Some(SyncClientState::Client),
            "deleting" => Some(SyncClientState::Deleting),
            "idle" => Some(SyncClientState::Idle),
            "listing" => Some(SyncClientState::Listing),
            "uploading" => Some(SyncClientState::Uploading),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        SyncClientEvent::Null
    }

